const output = [];

const fieldLabels = {
  "Transcript": "TRANSCRIPT",
  "Supporting_Documents": "REFERENCE",
  "Company_Logo_s_": "LOGO"
};

const binaryData = $input.first().binary || {};

for (const [field, label] of Object.entries(fieldLabels)) {
  // Matches the field name exactly (single file) OR field name followed
  // by an index suffix like _0, _1 (n8n's format when multiple files are
  // uploaded to the same field)
  const matchingKeys = Object.keys(binaryData).filter(
    (key) => key === field || key.startsWith(field + "_")
  );

  for (const key of matchingKeys) {
    const file = binaryData[key];
    output.push({
      json: { label, filename: file.fileName || "unknown" },
      binary: { data: file }
    });
  }
}

return output;

let context = "";

for (const item of $input.all()) {
  let label = item.json.label;
  let filename = item.json.filename;

  if (!label) {
    const idx = item.pairedItem?.item ?? 0;
    const source = $('Flatten Uploads').all()[idx];
    label = source?.json?.label || "UNKNOWN";
    filename = source?.json?.filename || "unknown";
  }

  const text = item.json.text || item.json.data || "";
  context += `\n=== [${label}: ${filename}] ===\n${text}\n`;
}

return [{ json: { context_block: context } }];

const items = $input.all();
if (items.length === 0) {
  return [{ json: { logo_data_uri: null } }];
}

const item = items[0];
const mimeType = item.binary?.data?.mimeType || "image/png";
const base64 = item.json.data || item.json.base64 || "";

return [{ json: { logo_data_uri: `data:${mimeType};base64,${base64}` } }];

const trigger = $('On form submission').first().json;
const merged = $input.first().json;

return [{
  json: {
    context_block: merged.context_block,
    logo_data_uri: merged.logo_data_uri,
    meta: {
      business_name: trigger['Company Name'] || null,
      trading_as: trigger['Trading as'] || null,
      location: trigger['Location'] || null,
      currency: trigger['Currency'] || 'AUD',
      client_url: trigger['Client URL'] || null
    },
    rate: trigger['Labour Rate'] || null
  }
}];

'use strict';

// HARDEN STATS PARSED
// Parses Node A's JSON and recomputes every dollar/hours figure from the
// underlying facts (hours, occurrences, rate). Node A stays responsible for
// reading the transcript and judging what "after" hours look like per
// automation level -- that's language understanding, code can't do it.
// This node just makes sure the arithmetic built on top of those judgments
// is always exactly right.

const LEVELS = ['low', 'medium', 'high'];

// 1. Get the raw text out of the Anthropic node's response shape
const raw = $input.first().json;
const rawText = raw && raw.content && raw.content[0] && raw.content[0].text;

if (!rawText) {
  throw new Error('Harden Stats Parsed: could not find content[0].text on the input -- check the Anthropic node output shape has not changed.');
}

// 2. Parse it
let data;
try {
  data = JSON.parse(rawText);
} catch (err) {
  throw new Error('Harden Stats Parsed: JSON.parse failed -- ' + err.message + '. Raw text started with: ' + rawText.slice(0, 200));
}

// 3. Basic structural sanity checks
if (!Array.isArray(data.workflows) || data.workflows.length < 1) {
  throw new Error('Harden Stats Parsed: workflows array is missing or empty.');
}

// 3b. Re-inject business_name from Final Build (Node A's own meta doesn't
// carry it), and record only a boolean has_logo flag -- never the raw
// base64 bytes. The actual logo data stays on Final Build permanently;
// Extract HTML reaches there directly, after generation, to do the real
// substitution. Keeping the raw bytes out of this node's output entirely
// means no future change to the HTTP body construction downstream can
// accidentally leak them into a model prompt -- there's nothing here to leak.
try {
  const finalBuildJson = $('Final Build').first().json;
  data.meta = data.meta || {};
  data.meta.business_name = (finalBuildJson.meta && finalBuildJson.meta.business_name) || null;
  data.meta.has_logo = !!finalBuildJson.logo_data_uri;
} catch (err) {
  throw new Error('Harden Stats Parsed: could not reach Final Build to re-inject business_name/has_logo -- ' + err.message);
}

const rate = Number(data.meta && data.meta.rate) || 0;
if (!rate) {
  throw new Error('Harden Stats Parsed: meta.rate is missing or zero -- cannot compute any dollar figures.');
}

const symbol = (data.meta && data.meta.currency_symbol) || '$';
const money = function (n) { return symbol + Math.round(n).toLocaleString('en-AU'); };
const hrs = function (n) { return (Math.round(n * 10) / 10).toString().replace(/\.0$/, ''); };

// 4. Recompute every workflow's figures at every level, from the raw facts
for (const wf of data.workflows) {
  const before = Number(wf.before && wf.before.hours_per_occurrence);
  const occ = Number(wf.occurrences_per_year);

  if (!Number.isFinite(before) || before < 0) {
    throw new Error('Harden Stats Parsed: workflow "' + wf.id + '" has an invalid before.hours_per_occurrence.');
  }
  if (!Number.isFinite(occ) || occ < 1 || occ > 10000) {
    throw new Error('Harden Stats Parsed: workflow "' + wf.id + '" has occurrences_per_year outside 1-10,000.');
  }

  for (const level of LEVELS) {
    const levelData = wf.levels && wf.levels[level];
    if (!levelData) {
      throw new Error('Harden Stats Parsed: workflow "' + wf.id + '" is missing levels.' + level + '.');
    }

    const after = Number(levelData.hours_after);
    if (!Number.isFinite(after) || after < 0) {
      throw new Error('Harden Stats Parsed: workflow "' + wf.id + '" levels.' + level + '.hours_after is invalid.');
    }
    if (after > before) {
      throw new Error('Harden Stats Parsed: workflow "' + wf.id + '" levels.' + level + '.hours_after (' + after + ') exceeds before.hours_per_occurrence (' + before + ').');
    }

    const savedHoursPerYear = Math.max(0, before - after) * occ;
    const annualSaving = savedHoursPerYear * rate;

    levelData.saved_hours_per_year = savedHoursPerYear;
    levelData.annual_saving = annualSaving;
    levelData.annual_saving_fmt = money(annualSaving);
  }
}

// 5. Recompute the audit-wide totals from the (now-hardened) workflow figures
const totals = {};
for (const level of LEVELS) {
  const savedHours = data.workflows.reduce(function (sum, wf) { return sum + wf.levels[level].saved_hours_per_year; }, 0);
  const annualSaving = data.workflows.reduce(function (sum, wf) { return sum + wf.levels[level].annual_saving; }, 0);

  totals[level] = {
    total_annual_saving: annualSaving,
    total_annual_saving_fmt: money(annualSaving),
    hours_freed_per_year: Math.round(savedHours),
    hours_freed_per_year_fmt: hrs(Math.round(savedHours)),
    hours_freed_per_week: Math.round((savedHours / 52) * 100) / 100,
    hours_freed_per_week_fmt: hrs(Math.round((savedHours / 52) * 100) / 100),
    cost_of_inaction_per_month: annualSaving / 12,
    cost_of_inaction_per_month_fmt: money(annualSaving / 12)
  };
}
data.totals = totals;

// 6. Resolve presentation_brief.headline_kpis from structured references
// into final display strings, using the hardened totals above -- Node A
// only chose WHICH metric matters, it never wrote a number. This is what
// stops a stale, unhardened figure from riding along inside prose text.
const METRIC_LABELS = {
  total_annual_saving: 'Total annual saving',
  hours_freed_per_year: 'Hours freed per year',
  hours_freed_per_week: 'Hours freed per week',
  cost_of_inaction_per_month: 'Cost of inaction per month'
};

function resolveHeadlineKpis(brief, totalsByLevel, keyIndicators) {
  if (!brief || !Array.isArray(brief.headline_kpis)) return [];

  return brief.headline_kpis.map(function (item) {
    if (item.metric === 'key_indicator') {
      const match = (keyIndicators || []).find(function (ki) {
        return ki.label === item.key_indicator_label;
      });
      if (!match) {
        return item.key_indicator_label + ' (figure unavailable -- label did not match key_indicators)';
      }
      return match.label + ' (' + match.value_fmt + ')';
    }

    const label = METRIC_LABELS[item.metric];
    const levelData = totalsByLevel && totalsByLevel[item.level];
    if (!label || !levelData) {
      return 'Unresolved headline KPI reference: ' + JSON.stringify(item);
    }

    const fmtValue = levelData[item.metric + '_fmt'];
    return label + ' at ' + item.level + ' automation level (' + fmtValue + ')';
  });
}

if (data.presentation_brief) {
  data.presentation_brief.headline_kpis = resolveHeadlineKpis(data.presentation_brief, totals, data.key_indicators);
}

return [{ json: data }];

'use strict';

// EXTRACT HTML
// Pulls the raw HTML document out of Node B's response, substitutes the real
// logo data into the placeholder Node B wrote, and turns the result into a
// downloadable binary file. Guards against a truncated or malformed response
// by checking the document actually looks like a complete HTML page before
// saving it -- fails loudly with a useful snippet rather than silently
// producing a broken file.

const PLACEHOLDER = '__LOGO_DATA_URI__';

const raw = $input.first().json;
const html = raw && raw.content && raw.content[0] && raw.content[0].text;

if (!html) {
  throw new Error('Extract HTML: could not find content[0].text on the input -- check the Anthropic API response shape has not changed.');
}

const trimmed = html.trim();

const startsOk = /^<!DOCTYPE html>/i.test(trimmed);
const endsOk = /<\/html>\s*$/i.test(trimmed);

if (!startsOk || !endsOk) {
  throw new Error(
    'Extract HTML: response does not look like a complete HTML document. ' +
    'starts_with_doctype=' + startsOk + ', ends_with_html_tag=' + endsOk + '. ' +
    'First 200 chars: ' + trimmed.slice(0, 200) + ' ... ' +
    'Last 200 chars: ' + trimmed.slice(-200)
  );
}

// Filename is cosmetic -- business_name comes from Harden Stats Parsed, which
// re-injects it from Final Build. A generic name is an acceptable fallback, so
// this failure is swallowed deliberately.
let fileName = 'audit-dashboard.html';
try {
  const businessName = $('Harden Stats Parsed').first().json.meta.business_name;
  if (businessName) {
    const slug = String(businessName)
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');
    if (slug) {
      fileName = slug + '-audit-dashboard.html';
    }
  }
} catch (err) {
  // Harden Stats Parsed not found or shape changed -- use the default name.
}

// The logo BYTES deliberately do NOT travel through Harden Stats Parsed:
// Harden's output is stringified wholesale into Node B's user message, so
// putting base64 there would undo the placeholder design and put the image
// data back in front of the model. Harden carries meta.has_logo only; the
// real bytes are read here, from Final Build, after generation is finished.
//
// Unlike the filename lookup above, this one is NOT cosmetic and must not be
// swallowed -- defaulting to null on error would silently drop a real logo
// and ship the placeholder as a dead literal string.
let logoDataUri = null;
try {
  logoDataUri = $('Final Build').first().json.logo_data_uri || null;
} catch (err) {
  throw new Error('Extract HTML: could not reach Final Build to resolve the logo -- ' + err.message);
}

const hasPlaceholder = trimmed.indexOf(PLACEHOLDER) !== -1;

if (logoDataUri && !hasPlaceholder) {
  throw new Error('Extract HTML: a logo was uploaded but Node B did not emit the ' + PLACEHOLDER + ' placeholder anywhere in its output. The dashboard would ship with no logo.');
}
if (!logoDataUri && hasPlaceholder) {
  throw new Error('Extract HTML: Node B emitted the ' + PLACEHOLDER + ' placeholder but no logo_data_uri exists on Final Build. The img src would be left as a dead literal string.');
}

// split/join rather than .replace(): a string-pattern replace only hits the
// first occurrence, and join sidesteps $&-style substitution patterns in the
// replacement value entirely.
const finalHtml = logoDataUri
  ? trimmed.split(PLACEHOLDER).join(logoDataUri)
  : trimmed;

return [{
  json: {},
  binary: {
    data: {
      data: Buffer.from(finalHtml).toString('base64'),
      mimeType: 'text/html',
      fileName: fileName
    }
  }
}];

